# Textos en català de les tires còmiques (mateix ordre de vinyetes i bocadillos que els .md en castellà)
T = {
"L_pressupost": [["El client m'ha demanat deu canvis més! Els hi faig gratis, per simpatia."], ["Eren al pressupost?", "Cal posar els canvis al pressupost?"], ["L'abast diu què inclou i què no. El que no hi és, es pressuposta a part."]],
"L_directoris": [["He fet un web preciós i Google no em troba."], ["L'has donat d'alta a Search Console? I la fitxa de Google?", "Cal presentar-se a Google? Com en una entrevista?"], ["Més o menys. I amb el mateix nom, adreça i telèfon a tot arreu."]],
"L_atribucio": [["Google diu que vaig vendre 100. Meta, 100. TikTok, 50. 250 vendes!"], ["I la botiga diu 160.", "Algú menteix?"], ["Cada plataforma s'atribueix les mateixes vendes. Per saber què funciona de debò, fes proves amb grup de control."]],
"L_blog": [["El meu blog tindrà 100 articles el primer dia!"], ["I el segon dia?", "Hi ha segon dia?"], ["Un blog viu de la constància: un calendari realista i temes que responguin als teus clients."]],
"L_newsletter": [["He comprat una llista de 10.000 correus. Demà envio la newsletter!"], ["Això és il·legal, ECO.", "Il·legal? Si eren barats!"], ["Només a qui s'ha subscrit, amb doble opt-in i un enllaç per donar-se de baixa."]],
"L_comunitats": [["He afegit els meus 500 clients a un grup de WhatsApp!"], ["Sense demanar-los permís?", "És que sortien a la meva agenda…"], ["Permís sempre. I als fòrums i grups: llegeix les normes i aporta valor abans de vendre."]],
"L_ads1": [["Anunci per al gimnàs de Vic: públic, tot el planeta!"], ["Algú del Japó vindrà a entrenar a Vic?", "Si l'anunci és molt bo…"], ["Objectiu clar, públic proper i mesura les conversions. Si no, no sabràs què ha funcionat."]],
"L_crisi": [["Hi ha queixes a Instagram! Esborro tots els comentaris."], ["I llavors en vindran el doble.", "Com ho saps?"], ["Primer entén què ha passat, disculpa't si toca i explica com ho arregles."]],
"L_web20": [["Compraré 200 ressenyes de cinc estrelles!"], ["Són falses i estan prohibides.", "I com aconsegueixo ressenyes?"], ["Demana-les a clients reals, respon-les totes i mostra al teu web el que diuen de tu."]],
"L_contractar": [["He contractat tres persones! Ja pensaré com pagar-les."], ["Amb quins ingressos fixos?", "Els sous són cada mes?"], ["Contracta quan tinguis ingressos recurrents. I delega amb objectius clars, no llançant tasques."]],
"L_crm": [["Tinc les dades dels clients en 14 llibretes."], ["I com saps a qui has de trucar aquesta setmana?", "Obro llibretes a l'atzar."], ["Un CRM ordena contactes i seguiments. Automatitza el que és repetitiu i protegeix les dades."]],
"L_ads2": [["El meu anunci té un munt de clics! Però no venc res."], ["Si l'anunci atreu, el problema és després del clic.", "Després del clic hi ha alguna cosa?"], ["La pàgina de destinació i la mesura. Mira el CTR, el CPA i el ROAS junts."]],
"L_domini": [["Domini de la botiga: bicis-barates-osona-online-24h.net"], ["I qui se'n recordarà, d'això?", "Jo… si ho apunto."], ["Curt, clar i a nom de l'empresa: osonabikes.cat. I publica de manera segura."]],
"L_clientonline": [["Els meus clients compren així que veuen el producte."], ["Ara comparen preus, llegeixen opinions i miren el mòbil…", "Abans de comprar? Quins desconfiats!"], ["És el client en línia: informat i omnicanal. Has d'estar bé a tots els canals."]],
"L_xarxes": [["He sortejat un mòbil i tinc 5.000 seguidors nous!"], ["Per a una botiga de llana?", "Els seguidors no són tots iguals?"], ["Han vingut pel mòbil, no per la llana. Millor menys seguidors, però interessats."]],
"L_html": [["El meu web té deu títols principals! Així Google veu que tot és important."], ["Deu h1?", "h1? És una autopista?"], ["És el títol principal. Un per pàgina, imatges amb text alternatiu i un menú clar."]],
"L_financament": [["Un inversor em dona diners gratis!"], ["Ningú no dona diners gratis.", "Vol alguna cosa a canvi?"], ["Una part de la teva empresa i créixer ràpid. Valora si et convé o si és millor que creixis amb beneficis."]],
"L_ia": [["La IA escriurà i publicarà tots els meus textos sola!"], ["Sense que ningú els revisi?", "Per a què la tinc si l'he de revisar?"], ["La IA fa esborranys; tu revises i decideixes. I mai posis dades de clients en qualsevol eina."]],
"L_metriques": [["El meu anunci ha tingut 20.000 impressions!"], ["I quantes persones han vingut a la botiga?", "Les impressions no són persones que compren?"], ["Són vegades que s'ha vist. Mira les mètriques a prop de la venda: visites, cupons, compres."]],
"L_fin": [["Aquest mes he facturat 3.000 €! Sóc ric!"], ["I quant has gastat?", "Gastar? Ah… 2.200 de lloguer, material, quotes…"], ["Llavors el teu benefici són 800 €. I si encara no t'han pagat, la teva caixa és a zero."]],
"L_recerca": [["La fleca ven poc a la tarda. Solució: TikTok!"], ["Has preguntat per què? Hi has anat a mirar?", "Eh… he vist un vídeo que diu que TikTok ho arregla tot."], ["Primer investiga: el símptoma no és la causa. Potser han tancat l'escola de davant."]],
"L_kpi": [["Aquest mes he publicat 30 vídeos!"], ["I què ha passat amb les vendes?", "Publicar 30 vídeos no és un resultat?"], ["És activitat. El resultat és el que aconsegueixes. I etiqueta els enllaços per saber d'on ve cada visita."]],
"L_marca": [["La meva agència treballa per a tothom: casaments, fàbriques i astronautes!"], ["I qui et recorda per alguna cosa?", "Els astronautes, segur."], ["Una marca clara atreu els clients adequats i allunya els que no encaixen. I això és bo."]],
"L_lideratge": [["Jo reviso tot, decideixo tot i faig tot!"], ["I per què el teu equip està aturat esperant-te?", "Perquè estic revisant…"], ["En créixer, es passa de fer a dirigir: objectius clars i confiança en l'equip."]],
"L_logistica": [["Comanda enviada! Ja arribarà quan arribi."], ["Li has enviat el número de seguiment?", "Cal avisar? Si és una sorpresa!"], ["Avisa, controla l'estoc i tracta bé les devolucions: una queixa ben resolta fidelitza."]],
"L_brief": [["L'anunci serà lila perquè és el meu color preferit."], ["I el públic? I el missatge principal?", "El públic també serà lila."], ["Un brief parteix de l'objectiu i del públic. I entre dues idees, decideix amb una prova A/B."]],
"L_afiliacio": [["Pagaré influencers per cada clic!"], ["I si els clics no compren?", "Un clic és una venda… no?"], ["En afiliació pagues per venda o contacte. I busca aliats complementaris, no competidors."]],
"L_b2b": [["La fàbrica em comprarà avui mateix! Només he d'enviar un correu."], ["En B2B decideix un comitè i el procés dura mesos.", "Mesos? Jo compro sabatilles en dos minuts!"], ["Per això el B2B necessita contingut útil, contactes qualificats i molt de seguiment."]],
"L_internacional": [["Per vendre a França, traduiré el web amb un traductor automàtic."], ["I els preus, el pagament i el servei?", "Els francesos no paguen amb euros?"], ["Sí, però localitzar és adaptar missatge, preus, pagament i servei al mercat. No només traduir."]],
"L_mobil": [["Enviaré SMS d'ofertes a tots els números que trobi!"], ["T'han donat permís?", "Cal permís per regalar ofertes?"], ["El mòbil és molt personal: permís, missatges útils i un web que es vegi bé en pantalla petita."]],
"L_onetoone": [["Envio el mateix correu als meus 3.000 clients! «Hola, client»."], ["I si cadascú rebés alguna cosa pensada per a ell?", "3.000 correus diferents? No tinc tantes mans!"], ["Per això hi ha el CRM. I sempre amb el seu permís."]],
"L_viral": [["Farem un vídeo viral! Ho he decidit aquest matí."], ["Allò viral no s'encarrega com una pizza.", "I si ho demano amb extra de formatge?"], ["Emoció, facilitat per compartir i un motiu per passar-ho a altres. I prepara't per als comentaris."]],
"L_models": [["Vendré formatges a Amazon, al meu web, a restaurants i en subhastes. Tot igual!"], ["Amb els mateixos preus per a un restaurant i per a un particular?", "B2B, B2C, D2C… són marques de cotxe?"], ["Són models de negoci. Cada canal necessita el seu catàleg, els seus preus i les seves condicions."]],
"L_normativa": [["El meu bàner de galetes només té el botó «Acceptar»! Així tothom accepta."], ["Això pot costar una multa.", "Per un botó?"], ["Rebutjar ha de ser tan fàcil com acceptar. I el client té 14 dies per desistir d'una compra en línia."]],
"L_smart": [["El meu objectiu: ser el número u!"], ["Número u en què? Quant? Per a quan?", "…En tot, moltíssim i ja?"], ["Millor: +15 % de vendes a la tarda en 4 setmanes. Específic, mesurable i amb termini."]],
"L_paginaxarxa": [["Venc des del meu perfil personal: foto de la platja i missatges privats."], ["I les condicions de venda? La factura?", "Calen per vendre un jersei?"], ["Perfil d'empresa, catàleg connectat, botó de compra i condicions clares."]],
"L_pagaments": [["A la meva botiga en línia només es pot pagar amb transferència."], ["I per què se'n van tants clients?", "Perquè no els agrada comprar?"], ["Ofereix el que fa servir el teu públic: targeta, Bizum, PayPal… amb pagament segur i verificació en dos passos."]],
"L_planificacio": [["Avui: canviar el color del logo. És urgentíssim!"], ["I la botiga en línia del client que no deixa comprar?", "Ui! Això també és d'avui?"], ["Prioritza per urgència i impacte. Primer el que fa perdre clients."]],
"L_posicionament": [["La meva agència es diferenciarà així: fem de tot per a tothom!"], ["Igual que les altres cent.", "I si baixo preus?"], ["Sempre hi haurà algú més barat. Busca alguna cosa certa, valuosa i difícil de copiar."]],
"L_processos": [["He perdut l'encàrrec del client! M'ho va demanar per WhatsApp, Instagram o al bar…"], ["I si totes les peticions entressin per un sol canal?", "I com em demanaran coses al bar?"], ["Un canal únic, cada tasca amb responsable i data, i una llista de comprovació abans de lliurar."]],
"L_prospeccio": [["Tinc 200 contactes de la fira! Tots clients segurs."], ["Quants tenen una necessitat, pressupost i pressa?", "Bé… 150 eren estudiants que volien bolígrafs."], ["Qualifica abans de vendre: necessitat, decisió, pressupost i urgència."]],
"L_experiments": [["L'anunci A va vendre 2 i el B, 1! L'A és el doble de bo!"], ["Amb tan poques vendes pot ser pura sort.", "La sort també fa màrqueting?"], ["Defineix el criteri abans de començar i espera a tenir prou dades."]],
"L_mkt": [["Ja faig màrqueting! He comprat 500 € d'anuncis."], ["I saps què necessita el teu client?", "Necessitar? Necessita veure els meus anuncis!"], ["Màrqueting és entendre necessitats i crear alguna cosa que les resolgui. Els anuncis vénen després."]],
"L_rendibilitat": [["El meu millor client em paga 1.000 € al mes!"], ["Quantes hores li dediques?", "Unes 50… ai, a 25 € l'hora!"], ["Et costa 1.250 €: perds diners. Parla amb ell per revisar l'abast o el preu."]],
"L_ltv": [["Aconsegueixo clients nous cada setmana!"], ["Quant et costa cada un i quant et deixa?", "Em costa 2.500 € i me'n deixa 2.000…"], ["Si el CAC és més gran que l'LTV, perds amb cada client. Cuida els que ja tens."]],
"L_seguretat": [["La meva contrasenya és «1234». Així no me n'oblido mai."], ["Ni els lladres.", "Me la poden endevinar?"], ["Contrasenyes llargues i úniques, verificació en dos passos, còpies de seguretat i web amb HTTPS."]],
"L_seo": [["He escrit «engranatges» 300 vegades al web."], ["I què cerca qui els vol comprar?", "Engranatges?"], ["Cerca «fabricant engranatges a mida pressupost». Escriu per a aquesta intenció, no per a un robot."]],
"L_seolocal": [["M'han posat una ressenya d'una estrella! L'esborraré."], ["No pots. Però pots respondre-la.", "Respondre? Per discutir?"], ["Per agrair, explicar què milloraràs… i fer-ho. Els pròxims clients ho llegiran."]],
"L_sem": [["Pago anuncis a Google i així puja la meva posició orgànica!"], ["No funciona així, ECO.", "SEO, SEM… no són el mateix amb una altra lletra?"], ["SEO és aparèixer sense pagar per clic. SEM són els anuncis. Una bona estratègia combina les dues."]],
"L_tresoreria": [["Tinc un sol client, però és enorme!"], ["I si demà se'n va?", "Els clients se'n poden anar?"], ["Reparteix el risc, demana bestretes i planifica la caixa dels pròxims mesos."]],
"L_ecom": [["2.000 visites a la meva botiga en línia!"], ["I quantes compres?", "30… molts se'n van en veure les despeses d'enviament."], ["Conversió de l'1,5 %. Mostra els costos des del principi i facilita el pagament."]],
"L_videotv": [["Pujaré a YouTube un vídeo de dues hores, sense subtítols!"], ["La majoria el deixa en els primers segons… i molts el veuen sense so.", "Sense so? I què senten?"], ["Comença fort, afegeix subtítols i adapta el format a cada plataforma."]],
"L_zones": [["El botó de comprar és a baix de tot! Així la gent llegeix tot el web."], ["El mapa de calor diu que ningú no arriba fins a baix.", "Hi ha un mapa del meu web? Amb tresors?"], ["Mostra on miren i fan clic. Posa l'important a dalt… i vigila la caixa de la botiga."]],
}
